class C { n = 1; bump(): number { this.n += 1; return this.n; } }
async function main(): Promise<void> {
  const nat: C[] = [new C()];
  const v: any = nat;
  const e = new C();
  v[1] = e;
  e.bump();
  console.log(v.length, nat.length, nat[1] === e, nat[1].n, v[1] === e, v[1].n);
  v.push(new C());
  console.log(nat.length, nat[2].n);
  const d = new C();
  const x: any = d;
  const y: any = [d];
  console.log(x === d, d === x, y[0] === d, y[0] === x, x !== d);
  const grid: number[][] = [[1]];
  const gv: any = grid;
  const inner = [5, 6];
  gv[0] = inner;
  inner.push(7);
  console.log(grid[0].length, inner.length, grid[0] === inner, gv[0] === inner);
  gv.push([9]);
  console.log(grid.length, grid[1][0]);
  const ref: any = nat;
  console.log(ref === nat, nat === ref);
}
